func (w *canonicalBuffer) encodeTypeRef(v *types.TypeRef) {
	if cached, ok := w.typeRefs[*v]; ok {
		w.data = append(w.data, cached...)
		return
	}
	start := len(w.data)
	w.data = append(w.data, '{')
	comma := false
	_ = comma
	if comma {
		w.data = append(w.data, ',')
	}
	comma = true
	w.data = append(w.data, "\"kind\":"...)
	w.data = strconv.AppendUint(w.data, uint64(v.Kind), 10)
	if v.Primitive != 0 {
		if comma {
			w.data = append(w.data, ',')
		}
		comma = true
		w.data = append(w.data, "\"primitive\":"...)
		w.data = strconv.AppendUint(w.data, uint64(v.Primitive), 10)
	}
	if comma {
		w.data = append(w.data, ',')
	}
	comma = true
	w.data = append(w.data, "\"named\":"...)
	w.encodeTypeKey(&v.Named)
	if len(v.Node) != 0 {
		if comma {
			w.data = append(w.data, ',')
		}
		comma = true
		w.data = append(w.data, "\"node\":"...)
		w.string(string(v.Node))
	}
	w.data = append(w.data, '}')
	if len(w.typeRefs) < 1024 && w.typeRefBytes+len(w.data)-start <= 256<<10 {
		if w.typeRefs == nil {
			w.typeRefs = make(map[types.TypeRef]string)
		}
		w.typeRefs[*v] = string(w.data[start:])
		w.typeRefBytes += len(w.data) - start
	}
}
